// iPhone screen sizes (portrait, CSS px) for the iOS PWA launch images.
// iOS only uses a startup image whose media query matches the device exactly.
// Images are generated by scripts/splash-images.mts into public/splash/.
export const IOS_SPLASH_DEVICES = [
  { width: 320, height: 568, ratio: 2, homeButton: true }, // SE (1st gen)
  { width: 375, height: 667, ratio: 2, homeButton: true }, // SE (2nd/3rd gen), 6–8
  { width: 414, height: 736, ratio: 3, homeButton: true }, // 6–8 Plus
  { width: 375, height: 812, ratio: 3, homeButton: false }, // X, XS, 11 Pro, 12/13 mini
  { width: 414, height: 896, ratio: 2, homeButton: false }, // XR, 11
  { width: 414, height: 896, ratio: 3, homeButton: false }, // XS Max, 11 Pro Max
  { width: 390, height: 844, ratio: 3, homeButton: false }, // 12, 13, 14, 16e
  { width: 428, height: 926, ratio: 3, homeButton: false }, // 12/13 Pro Max, 14 Plus
  { width: 393, height: 852, ratio: 3, homeButton: false }, // 14 Pro, 15, 15 Pro, 16
  { width: 430, height: 932, ratio: 3, homeButton: false }, // 14 Pro Max, 15 Plus/Pro Max, 16 Plus
  { width: 402, height: 874, ratio: 3, homeButton: false }, // 16 Pro, 17, 17 Pro
  { width: 420, height: 912, ratio: 3, homeButton: false }, // Air
  { width: 440, height: 956, ratio: 3, homeButton: false }, // 16 Pro Max, 17 Pro Max
] as const;

type Device = (typeof IOS_SPLASH_DEVICES)[number];

export function iosSplashPath(d: Device): string {
  return `/splash/iphone-${d.width * d.ratio}x${d.height * d.ratio}.png`;
}

export const iosStartupImages = IOS_SPLASH_DEVICES.map((d) => ({
  url: iosSplashPath(d),
  media: `(device-width: ${d.width}px) and (device-height: ${d.height}px) and (-webkit-device-pixel-ratio: ${d.ratio}) and (orientation: portrait)`,
}));
